const rawOutput = $input.item.json.stdout;
let data = {};
try {
  data = JSON.parse(rawOutput);
} catch (e) {
  data = { error: 'Failed parsing JSON', raw: rawOutput };
}

// Format KPI Scorecard for Executive View
const kpis = data.kpis || [];
const anomalies = data.anomalies || [];
const takeaways = data.strategic_takeaways || [];

const hasCriticalRisk = anomalies.some(a => a.severity === 'critical');
const totalRevenue = kpis.find(k => k.name.includes('Revenue'))?.value || 0;

return {
  json: {
    dataset: data.dataset,
    total_revenue: totalRevenue,
    execution_latency_ms: data.execution_ms,
    has_critical_risk: hasCriticalRisk,
    kpi_count: kpis.length,
    kpis: kpis,
    critical_anomalies: anomalies.filter(a => a.severity === 'critical' || a.severity === 'high'),
    strategic_takeaways: takeaways,
    executive_narrative: data.narrative_report,
    xai_proof: {
      verified_engine: 'DuckDB In-Memory (:memory:)',
      sql_sample: kpis[0]?.sql || 'N/A',
      rag_source: kpis[0]?.rag_source || 'N/A'
    }
  }
};

const data = $input.item.json;
const alertHeader = '🚨 [ALERTE CRITIQUE DIRECTION COMMERCIALE]

';
const summary = data.strategic_takeaways[0]?.summary || 'Perte de marge ou concentration critique détectée.';
const action = data.strategic_takeaways[0]?.action || 'Audit immédiat des prix et de la rentabilité.';

const message = `${alertHeader}Dataset: ${data.dataset}
Chiffre d'Affaires: $${data.total_revenue.toLocaleString()}
Latence DuckDB: ${data.execution_latency_ms} ms

${summary}

Action Prioritaire:
👉 ${action}

Preuve XAI (Requête SQL):
${data.xai_proof.sql_sample}`;

return { json: { alert_message: message, status: 'ALERT_TRIGGERED', ...data } };

const data = $input.item.json;
const header = '✅ [RAPPORT BI STANDARD COMEX]

';
const message = `${header}Dataset: ${data.dataset}
Chiffre d'Affaires: $${data.total_revenue.toLocaleString()}
Performance: Conforme aux seuils opérationnels.

Preuve SQL DuckDB:
${data.xai_proof.sql_sample}`;

return { json: { report_message: message, status: 'NOMINAL', ...data } };
